import {UNITS,QUOTES,money,toCents,equalShares,initialState,quoteFor,paid,transition,validateState,serializeSummary,forecast,syntheticHistory} from './core.mjs';
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='pipa-demo-v1'; let state=initialState(), storageBlocked=false, tab='resumen', toastTimer;
const stageName={draft:'Por confirmar',confirmed:'Confirmado',review:'Revisar entrega',closed:'Cuenta cerrada'};
const navNames={resumen:'Resumen',pedido:'Pedido de agua',aportaciones:'Aportaciones',cisterna:'Cisterna y entrega',historial:'Historial'};
function storageWarning(text){$('#storage-warning').textContent=text;$('#storage-warning').hidden=false;}
try{const raw=localStorage.getItem(KEY);if(raw)state=validateState(JSON.parse(raw));}catch{storageBlocked=true;storageWarning('No se pudo recuperar el registro. Ves una demo temporal; no sobrescribiremos el original. Usa «Reiniciar demostración» para empezar de nuevo.');}
function notify(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,5000);}
function save(next){state=next;if(!storageBlocked){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageWarning('El navegador no permite guardar. Puedes continuar en esta pestaña, pero los cambios se perderán al cerrarla.');}}}
function act(action,data){save(transition(state,action,data));render();}
function navigate(name){location.hash=name;}
function heading(eyebrow,title,subtitle,action=''){return `<div class="view-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div>${action}</div>`;}
function steps(){const index={draft:1,confirmed:2,review:2,closed:3}[state.stage];return `<div class="steps">${['Cotizar','Confirmar','Recibir'].map((s,i)=>`${i?'<span class="step-line"></span>':''}<span class="step ${i<index?'done':''}"><i>${i<index?'✓':i+1}</i>${s}</span>`).join('')}</div>`;}
function orderCard(){const q=quoteFor(state);return `<section class="card"><div class="card-head"><div><h2>El próximo pedido</h2><p class="order-number">JACARANDA / PEDIDO DEMO 001</p></div><span class="tag ${state.stage==='draft'?'amber':''}">${stageName[state.stage]}</span></div>${steps()}<div class="order-metrics"><div><div class="metric-number">${money(q.cents)}<small>MXN</small></div><span class="metric-label">Precio total acordado</span></div><div><div class="metric-number">${q.liters.toLocaleString('es-MX')}<small>L</small></div><span class="metric-label">Cotizados · aún no certificados</span></div></div><p class="note">${esc(q.window)} · ${esc(q.name)}</p><div class="action-row"><a class="primary" href="#${state.stage==='draft'?'pedido':'cisterna'}">${state.stage==='draft'?'Revisar y confirmar':'Ver entrega'} <span aria-hidden="true">→</span></a><button class="text-button" data-summary>Vista previa del resumen</button></div></section>`;}
function tankCard(){const level=state.delivery?.after??62, reserve=(state.delivery?.capacity??10000)*level/100,f=forecast(syntheticHistory(),reserve);return `<section class="card"><div class="card-head"><h2>Así va la cisterna</h2><span class="tag gray">SIMULACIÓN</span></div><div class="tank-layout"><div class="tank" role="img" aria-label="Nivel simulado de cisterna ${level}%"><div class="water" style="height:${level}%"></div><span class="water-label">${level}%</span></div><div class="tank-ticks"><span>100%</span><span>75%</span><span>50%</span><span>25%</span><span>0%</span></div></div><div class="reserve"><span>Reserva orientativa<br><small>Modelo con historial sintético</small></span><b>${f.days.toFixed(1)} días</b></div><p class="note">${f.low.toFixed(1)}–${f.high.toFixed(1)} días según el error de prueba. No predice el suministro público.</p><div class="action-row"><a class="link-arrow" href="#cisterna">Ver lecturas y modelo →</a></div></section>`;}
function table(){return `<div class="table-wrap"><table><caption class="sr-only">Aportaciones por departamento ficticio</caption><thead><tr><th>Departamento</th><th>Acordado</th><th>Registrado</th><th>Estado</th></tr></thead><tbody>${UNITS.map(u=>{const p=paid(state,u),due=state.shares[u];return `<tr><td><span class="unit-avatar" aria-hidden="true">${u}</span><b>Depto. ${u}</b></td><td>${money(due)}</td><td>${money(p)}</td><td><span class="tag ${p>=due?'':p?'amber':'gray'}">${p>=due?'Completo':p?'Parcial':'Por registrar'}</span></td></tr>`}).join('')}</tbody></table></div>`;}
function contributionsCard(){const done=UNITS.filter(u=>paid(state,u)>=state.shares[u]).length;return `<section class="card section-space"><div class="card-head"><div><h2>Las cuentas, a la vista</h2><p class="muted">Reparto acordado. Los saldos no condicionan el agua.</p></div><div class="progress-box"><p class="muted">${done} de 4 completas</p><div class="progress-track"><div class="progress-fill" style="width:${done*25}%"></div></div></div></div>${table()}<div class="action-row"><a class="link-arrow" href="#aportaciones">${state.stage==='draft'?'Ver reparto':'Registrar una aportación'} →</a></div></section>`;}
function overview(){return heading('MENOS VUELTAS. MÁS CLARIDAD.','El agua, las cuentas claras.','Organiza la pipa, cuida la cisterna y comparte la responsabilidad.')+`<div class="grid">${orderCard()}${tankCard()}</div>${contributionsCard()}<div class="privacy-banner"><span class="privacy-icon" aria-hidden="true">⊙</span><div><b>El registro se queda en tu dispositivo.</b><p>Solo sale el resumen que tú decidas copiar o imprimir. Todas las cifras y los proveedores de esta demo son ficticios.</p></div></div>`;}
function order(){const q=quoteFor(state);return heading('UN PEDIDO. UN ACUERDO.','Elige con las cuentas claras.','Cotizaciones ficticias para explorar el flujo. No se contratan servicios reales.')+`<div class="quote-grid">${QUOTES.map(item=>`<section class="quote ${q.id===item.id?'selected':''}"><h3>${item.name}</h3><div class="metric-number">${money(item.cents)}</div><p class="muted">${item.liters.toLocaleString('es-MX')} L cotizados · ${money(item.cents/item.liters*1000)} / 1,000 L</p><p class="field-help">${item.window}</p><button class="${q.id===item.id?'primary':'secondary'}" data-quote="${item.id}" ${state.stage!=='draft'?'disabled':''}>${q.id===item.id?'Seleccionada':'Elegir cotización'}</button></section>`).join('')}</div><section class="card section-space"><h2>Un reparto que todos entiendan</h2><p class="muted">La cisterna es compartida. Estas cuotas son un acuerdo, no una medición de consumo por vivienda.</p><form id="allocation-form" novalidate><div class="action-row"><button type="button" class="secondary button-small" id="equal" ${state.stage!=='draft'?'disabled':''}>Dividir en partes iguales</button></div>${UNITS.map(u=>`<div class="allocation-row"><label for="share-${u}">Depto. ${u} · MXN</label><input id="share-${u}" name="${u}" type="number" inputmode="decimal" min="0" max="1000000" step="0.01" value="${(state.shares[u]/100).toFixed(2)}" ${state.stage!=='draft'?'disabled':''} aria-describedby="allocation-error"></div>`).join('')}<div class="balance-callout"><span>Total de la cotización</span><b>${money(q.cents)} MXN</b></div><p id="allocation-error" class="form-message" role="alert"></p><button class="primary" ${state.stage!=='draft'?'disabled':''}>Confirmar pedido y reparto →</button>${state.stage!=='draft'?'<p class="note">Pedido confirmado. Para cambiar una aportación registrada, anúlala desde Aportaciones. El reparto queda conservado.</p>':''}</form></section>`;}
function contributions(){const active=['confirmed','review'].includes(state.stage);return heading('CADA APORTACIÓN CUENTA.','Sin perseguir mensajes.','Registra efectivo o transferencia. La aplicación no recibe ni mueve dinero.')+`<div class="grid"><section class="card"><div class="card-head"><h2>Reparto del pedido</h2><span class="tag gray">4 viviendas ficticias</span></div>${table()}<p class="note">Solo coordinación ve este registro local. El resumen compartible omite saldos individuales.</p></section><section class="card"><h2>Registrar aportación</h2>${!active?`<p class="notice section-space">${state.stage==='draft'?'Primero confirma el pedido y el reparto.':'La cuenta está cerrada; su historial se conserva.'}</p>`:''}<form id="payment-form" novalidate><div class="form-grid section-space"><div><label for="unit">Departamento</label><select id="unit" name="unit" ${!active?'disabled':''}>${UNITS.map(u=>`<option value="${u}">Departamento ${u}</option>`).join('')}</select></div><div><label for="method">Método</label><select id="method" name="method" ${!active?'disabled':''}><option value="cash">Efectivo</option><option value="transfer">Transferencia</option></select></div><div class="full"><label for="amount">Monto recibido · MXN</label><input id="amount" name="amount" placeholder="Ej. 450.00" inputmode="decimal" type="number" min="0.01" max="1000000" step="0.01" ${!active?'disabled':''} aria-describedby="payment-error"><p class="field-help">No agregues nombres, cuentas ni datos personales.</p></div></div><p class="form-message" id="payment-error" role="alert"></p><button class="primary" ${!active?'disabled':''}>Guardar aportación</button></form></section></div><section class="card section-space"><h2>Movimientos y correcciones</h2>${state.payments.length?`<div class="table-wrap"><table><thead><tr><th>Movimiento</th><th>Monto</th><th>Método</th><th>Acción</th></tr></thead><tbody>${state.payments.map(p=>`<tr><td>Depto. ${p.unit} · #${p.id}</td><td>${money(p.cents)}</td><td>${p.method==='cash'?'Efectivo':'Transferencia'}</td><td>${p.voided?'<span class="tag gray">Anulado</span>':`<button class="secondary button-small" data-void="${p.id}" ${!active?'disabled':''}>Anular registro</button>`}</td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">Todavía no hay movimientos. Los registros anulados también se conservarán aquí.</p>'}</section>`;}
function delivery(){const d=state.delivery,closed=state.stage==='closed',draft=state.stage==='draft',level=d?.after??62,f=forecast(syntheticHistory(),(d?.capacity??10000)*level/100);return heading('VER EL NIVEL. ENTENDER LA ENTREGA.','La cisterna también cuenta.','Sensor y entrenamiento simulados. Toda estimación requiere revisión humana.')+`<div class="grid"><section class="card"><div class="card-head"><h2>Registrar entrega</h2><span class="tag gray">Lectura manual · demo</span></div>${draft?'<div class="notice">Confirma primero el pedido en Pedido de agua.</div>':''}<form id="delivery-form" novalidate><div class="form-grid">${[['capacity','Capacidad calibrada · L',d?.capacity??10000,100,100000],['before','Nivel antes · %',d?.before??20,0,100],['after','Nivel después · %',d?.after??65,0,100],['withdrawals','Consumo durante llenado · L',d?.withdrawals??500,0,100000]].map(([name,label,value,min,max])=>`<div><label for="${name}">${label}</label><input id="${name}" name="${name}" type="number" inputmode="decimal" min="${min}" max="${max}" step="any" value="${value}" aria-describedby="delivery-error" ${closed||draft?'disabled':''}></div>`).join('')}<label class="check-label full"><input type="checkbox" name="calibrated" id="calibrated" ${d?'checked':''} ${closed||draft?'disabled':''}>Para esta demo, confirmo una escala de nivel calibrada a volumen. Un porcentaje de altura sin calibración no basta.</label></div><p class="field-help">Entrega estimada = capacidad × cambio de nivel + consumo durante el llenado. No certifica calidad ni demuestra fraude.</p><p class="form-message" id="delivery-error" role="alert"></p><button class="primary" ${closed||draft?'disabled':''}>${d?'Corregir lecturas':'Calcular y registrar entrega'}</button></form></section>${tankCard()}</div>${d?`<section class="card section-space"><div class="card-head"><h2>Revisión de entrega</h2><span class="tag ${d.reviewed?'':'amber'}">${d.reviewed?'Revisada':'Requiere revisión'}</span></div><div class="order-metrics"><div><div class="metric-number">${quoteFor(state).liters.toLocaleString('es-MX')}<small>L</small></div><span class="metric-label">Volumen cotizado</span></div><div><div class="metric-number">${d.liters.toLocaleString('es-MX')}<small>L</small></div><span class="metric-label">Volumen estimado</span></div></div><p class="notice section-space">Diferencia: ${(d.liters-quoteFor(state).liters).toLocaleString('es-MX')} L. Revisa la escala, los retiros y el comprobante con el proveedor. Esta diferencia no permite acusar ni retener pagos automáticamente.</p><div class="action-row"><button id="review-delivery" class="secondary" ${d.reviewed||closed?'disabled':''}>He revisado la diferencia</button><button id="close-order" class="primary" ${!d.reviewed||closed?'disabled':''}>${closed?'Cuenta cerrada':'Cerrar cuenta con revisión'}</button></div><p class="note">Cerrar conserva los saldos y el historial. No bloquea el agua de ninguna vivienda.</p></section>`:''}<section class="card section-space"><div class="card-head"><h2>Modelo de consumo · entrenamiento sintético</h2><span class="tag amber">ML DEMOSTRATIVO</span></div><p class="muted">Regresión lineal entrenada aquí con 21 días sintéticos; 7 días posteriores separados para prueba. La comparación es contra repetir el último consumo de entrenamiento.</p><div class="bars" role="img" aria-label="28 días de consumo sintético; 21 de entrenamiento y 7 de prueba">${syntheticHistory().map((r,i)=>`<i class="${i>=21?'holdout':''}" style="height:${r.liters/18}%"></i>`).join('')}</div><div class="ml-stats"><div><span class="muted">Error del modelo</span><strong>${f.mae.toFixed(0)} L/día</strong></div><div><span class="muted">Error de referencia</span><strong>${f.baseline.toFixed(0)} L/día</strong></div><div><span class="muted">Siguiente consumo</span><strong>${f.consumption.toFixed(0)} L/día</strong></div></div><p class="note">${f.best?'El modelo supera la referencia en estos datos sintéticos.':'Se usa la referencia porque el modelo no la supera.'} No está validado con hogares reales ni anticipa la llegada del agua. Ninguna recomendación compra, cobra o asigna agua.</p></section>`;}
function history(){return heading('UN REGISTRO QUE SE PUEDE CORREGIR.','Lo que pasó, paso a paso.','La corrección añade un movimiento. No borra el registro anterior.',`<button class="secondary" data-summary>Preparar resumen</button>`)+`<section class="card"><h2>Historial de este pedido</h2>${state.events.length?`<ol class="timeline">${[...state.events].reverse().map(e=>`<li><b>${esc(e.detail)}</b><time>${esc(new Date(e.at).toLocaleString('es-MX'))}</time></li>`).join('')}</ol>`:'<p class="empty">Tu primera acción aparecerá aquí. Elige una cotización para comenzar.</p>'}</section>`;}
function modal(html){$('#modal-content').innerHTML=html;$('#modal').showModal();}
function showSummary(){modal(`<h2>Revisa antes de compartir</h2><p>Solo se incluyen totales del pedido. Aunque no aparecen viviendas individuales, un total puede revelar información en grupos pequeños. Tú eliges si lo compartes.</p><pre class="summary" id="summary-text">${esc(serializeSummary(state))}</pre><div class="action-row"><button id="copy-summary" class="primary">Copiar resumen</button><button class="secondary" id="print-summary">Imprimir resumen</button></div>`);$('#copy-summary').onclick=async()=>{try{await navigator.clipboard.writeText(serializeSummary(state));notify('Resumen copiado. Tú eliges dónde compartirlo.');}catch{notify('No se pudo copiar. Selecciona el texto del resumen y cópialo manualmente.');}};$('#print-summary').onclick=()=>window.print();}
function form(id,error,handler){const f=$(id);if(f)f.onsubmit=e=>{e.preventDefault();try{handler(new FormData(f));}catch(err){$(error).textContent=err.message;$(error).setAttribute('tabindex','-1');$(error).focus();}};}
function render(){
  tab=navNames[location.hash.slice(1)]?location.hash.slice(1):'resumen';
  $('#crumb').textContent=navNames[tab];document.querySelectorAll('[data-tab]').forEach(a=>{a.classList.toggle('active',a.dataset.tab===tab);if(a.dataset.tab===tab)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
  $('#view').innerHTML=({resumen:overview,pedido:order,aportaciones:contributions,cisterna:delivery,historial:history}[tab])();
  document.querySelectorAll('[data-summary]').forEach(b=>b.onclick=showSummary);
  document.querySelectorAll('[data-quote]').forEach(b=>b.onclick=()=>{try{act('quote',{id:b.dataset.quote});notify('Cotización seleccionada. Revisa el reparto antes de confirmar.');}catch(e){notify(e.message)}});
  if($('#equal'))$('#equal').onclick=()=>{const shares=equalShares(quoteFor(state).cents);UNITS.forEach(u=>$(`#share-${u}`).value=(shares[u]/100).toFixed(2));};
  form('#allocation-form','#allocation-error',fd=>{const shares=Object.fromEntries(UNITS.map(u=>[u,fd.get(u)==='0'||fd.get(u)==='0.00'?0:toCents(fd.get(u))]));act('confirm',{shares});navigate('aportaciones');notify('Pedido confirmado. Ya puedes registrar aportaciones.');});
  form('#payment-form','#payment-error',fd=>{act('payment',{unit:fd.get('unit'),method:fd.get('method'),cents:toCents(fd.get('amount'))});notify('Aportación registrada. No se realizó un pago real.');});
  form('#delivery-form','#delivery-error',fd=>{act('delivery',{capacity:fd.get('capacity'),before:fd.get('before'),after:fd.get('after'),withdrawals:fd.get('withdrawals'),calibrated:fd.get('calibrated')==='on'});notify('Entrega registrada. Revisa la diferencia antes de cerrar.');});
  document.querySelectorAll('[data-void]').forEach(b=>b.onclick=()=>{modal('<h2>¿Anular esta aportación?</h2><p>El registro original se conserva como anulado. El saldo vuelve a estar pendiente. No se mueve dinero.</p><button class="danger" id="confirm-void">Sí, anular registro</button>');$('#confirm-void').onclick=()=>{try{act('voidPayment',{id:Number(b.dataset.void)});$('#modal').close();notify('Aportación anulada; historial conservado.');}catch(e){notify(e.message)}};});
  if($('#review-delivery'))$('#review-delivery').onclick=()=>{act('review',{accepted:true});notify('Revisión registrada.');};
  if($('#close-order'))$('#close-order').onclick=()=>{modal('<h2>¿Cerrar esta cuenta?</h2><p>Se conservarán las lecturas, las aportaciones y los saldos pendientes. Este pedido quedará solo para consulta. Ningún saldo bloquea el acceso al agua.</p><button class="primary" id="confirm-close">Confirmar cierre</button>');$('#confirm-close').onclick=()=>{act('close');$('#modal').close();notify('Cuenta cerrada. Puedes exportar el resumen.');};};
}
$('#modal-close').onclick=()=>$('#modal').close();
$('#reset').onclick=()=>{modal('<h2>¿Reiniciar la demostración?</h2><p>Se eliminará únicamente este registro ficticio del navegador. Cancela si quieres conservarlo o imprime primero un resumen.</p><button class="danger" id="confirm-reset">Sí, reiniciar demo</button>');$('#confirm-reset').onclick=()=>{storageBlocked=false;try{localStorage.removeItem(KEY);$('#storage-warning').hidden=true;}catch{storageWarning('El almacenamiento está bloqueado. Continuarás con una demo temporal.');}save(initialState());$('#modal').close();navigate('resumen');render();notify('Demostración reiniciada.');};};
$('#privacy').onclick=()=>modal('<h2>Un registro para las personas</h2><p>Esta demo usa proveedores y viviendas ficticios. No introduzcas nombres ni información personal. Los registros se guardan solo en este navegador; quien tenga acceso a este dispositivo puede verlos. Borrar los datos del navegador elimina la demo.</p><p>No hay sincronización entre dispositivos, pagos reales, contratación de pipas, puntuaciones de vecinos ni decisiones automáticas sobre agua. El modelo se entrena con datos sintéticos y el sensor es simulado.</p><p>Solo al copiar o imprimir se prepara un resumen agregado. El servidor de alojamiento puede registrar solicitudes técnicas de páginas, pero la aplicación no envía tus lecturas ni aportaciones.</p>');
window.addEventListener('hashchange',()=>{render();$('#main').focus();window.scrollTo(0,0);});
window.addEventListener('storage',e=>{if(e.key!==KEY)return;try{state=e.newValue?validateState(JSON.parse(e.newValue)):initialState();render();notify('Registro actualizado desde otra pestaña.');}catch{storageWarning('Otra pestaña guardó un formato no válido. Recarga o reinicia la demostración.');}});
render();
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
